import assert from "node:assert/strict";
import { appendFileSync } from "node:fs";
import { createInterface } from "node:readline";
import { gzipSync } from "node:zlib";
import { buildChoice } from "./build-choice";
import { fightNative, hash } from "./native";
import { SearchDriver } from "./sources/common/src/simulation/search_driver";
import { permuteRankedDraftSeed } from "./sources/common/src/simulation/ranked_draft_eval";
import { V08_A19_PROFILE_SCHEMA } from "./sources/common/src/ai/versions/v0_8_a19_profile";
import { environment } from "./profiles";

assert.equal(V08_A19_PROFILE_SCHEMA,"hoc.v0_8_a19_production_profile.v11");
assert.equal(environment.SEARCH_ROLLOUTS,"2");
assert.equal(environment.SEARCH_HORIZON,"64");
assert.equal(environment.SEARCH_A19_ROLLOUT_ALLOCATION,"uniform");
assert.equal(environment.SEARCH_A19_MELEE_BARREL_DELIBERATION,"1");
assert.equal(environment.SEARCH_A19_NIGHTMARE_WALL_MOVEMENT,"1");
const [output,implementation]=process.argv.slice(2),g=globalThis as any;
assert(["baseline","candidate"].includes(implementation));
// Baseline keeps the actual native decision and neural predictor functions untouched.
// The candidate wrapper only activates the already frozen private treatment per actual driver.
if(implementation==="candidate"){
 const proto=SearchDriver.prototype as any,choose=proto.chooseDecision;
 proto.chooseDecision=function(unit:any,...args:any[]){
  const active=g.__mode==="both"||(g.__mode==="mixture"&&unit.getTeam()===g.__team);
  this.barrelForecastMixture=active;this.liveCertifiedBounds=active;
  if(active)g.__mixtureRoots++;
  return choose.call(this,unit,...args);
 };
}
for await(const line of createInterface({input:process.stdin})){
 const {job,registrationSha256}=JSON.parse(line);
 assert(["stock","mixture","both"].includes(job.mode));
 assert.equal(job.implementation,implementation);
 assert.equal(job.mode==="stock",implementation==="baseline");
 const team=(job.game<2)===(job.game%2===0)?2:1;
 const combatSeed=permuteRankedDraftSeed(job.seed+6+Number(job.game>=2));
 g.__mode="stock";g.__mixtureLiveMode=false;
 const built=buildChoice(job,"current","current",team);
 assert.equal(hash(built.drafted.config),job.draftConfigSha256[Number(job.game>=2)]);
 const inputSha256=hash({config:built.opening.config,teams:built.opening.teams,terrain:built.opening.terrain,combatSeed});
 assert.equal(inputSha256,job.expectedInputSha256);
 g.__mode=job.mode;g.__team=team;g.__mixtureLiveMode=job.live;g.__mixtureRoots=0;
 const actualTurns:any[]=[],decisionMicros:any[]=[];
 g.__rushTurn=(r:any)=>actualTurns.push({unitId:r.unitId,creatureName:r.creatureName,rawIncumbent:r.rawIncumbent,chosenDecision:r.chosenDecision});
 g.__mixtureDecisionCompleted=(o:any)=>{
  assert.equal(o.context.a19BarrelIntentForecast,undefined,"Projected flag reached an actual root");
  assert(Number.isFinite(o.context.decisionStartedAtMs));
  decisionMicros.push({team:o.unit.getTeam(),micros:Math.max(0,Math.round((performance.now()-o.context.decisionStartedAtMs)*1000))});
 };
 const cpu=process.cpuUsage(),started=performance.now();
 const fought=fightNative(structuredClone(built.opening),combatSeed);
 const fightWallMicros=Math.round((performance.now()-started)*1000),used=process.cpuUsage(cpu);
 assert.equal(fought.result.endReason,"elimination");
 const score=fought.result.winner==="draw"?.5:Number(fought.result.winner===(team===2?"green":"red"));
 if(job.mode!=="stock")assert(g.__mixtureRoots>0);
 for(const w of fought.quality.work)for(const key of["deadlineFallbacks","circuitSkipped","circuitWaitArbitrations","degradedDecisions"])assert.equal(w[key]??0,0);
 if(job.expectedTraceSha256){
  assert.equal(fought.traceSha256,job.expectedTraceSha256);
  assert.equal(score,job.expectedScore);assert.equal(fought.result.winner,job.expectedWinner);
 }
 const row={...job,registrationSha256,implementation,team,inputSha256,traceSha256:fought.traceSha256,
  score,winner:fought.result.winner,fightCpuMicros:used.user+used.system,fightWallMicros,
  decisionMicros,actualTurns,mixtureRoots:g.__mixtureRoots,quality:fought.quality};
 appendFileSync(output,gzipSync(JSON.stringify(row)+"\n",{level:1}));
 console.log(JSON.stringify({verified:true,jobId:job.jobId,mode:job.mode,implementation,
  inputSha256,traceSha256:fought.traceSha256,score,winner:fought.result.winner}));
}

