from pathlib import Path
import datetime,gzip,hashlib,json,math,sys

p=Path(__file__).resolve().parent
variant=sys.argv[1]if len(sys.argv)>1 else'primary'
assert variant in ['primary','coverage']
stem='v11-cost'if variant=='primary'else'v11-coverage-cost'
expected=464 if variant=='primary'else 1328
caseCount=72 if variant=='primary'else 216
out=p/stem
status=json.loads((out/'status.json').read_text())
assert status['complete']and not status['errors']and not status['liveWorkerPids']and status['fights']==expected
rawreg=(p/f'{stem}-registration.json').read_bytes();reg=json.loads(rawreg);seal=hashlib.sha256(rawreg).hexdigest()
assert reg['variant']==variant and reg['executions']==expected and reg['preselectedCases']==caseCount
for f in reg['files']:assert hashlib.sha256((p/f['path']).read_bytes()).hexdigest()==f['sha256'],f['path']
jobs={r['jobId']:r for r in json.loads((p/f'{stem}-jobs.json').read_text())}
original={(r['board'],r['game']):r['arms']for r in json.loads(gzip.decompress((p/'complete-trace-index.json.gz').read_bytes()))}
rows={};rawsha={}
for implementation in ['baseline','candidate']:
 f=out/f'{implementation}.jsonl.gz';raw=f.read_bytes();rawsha[f.name]=hashlib.sha256(raw).hexdigest()
 for line in gzip.decompress(raw).splitlines():
  r=json.loads(line);j=jobs[r['jobId']];assert r['jobId']not in rows
  assert r['registrationSha256']==seal and r['implementation']==implementation==j['implementation']
  for key in ['mode','phase','live','warmup','ordinal','board','game','seed']:assert r[key]==j[key]
  assert r['inputSha256']==j['expectedInputSha256']
  assert r['quality']['rejected']==0 and r['quality']['neural']and r['quality']['work']
  for n in r['quality']['neural']:assert n['modelErrors']==n['missingStart']==0
  for w in r['quality']['work']:assert all(w.get(k,0)==0 for k in ['deadlineFallbacks','circuitSkipped','circuitWaitArbitrations','degradedDecisions'])
  assert isinstance(r['fightCpuMicros'],int)and r['fightCpuMicros']>0
  assert isinstance(r['fightWallMicros'],int)and r['fightWallMicros']>0
  assert r['decisionMicros']and all(isinstance(d['micros'],int)and d['micros']>=0 for d in r['decisionMicros'])
  if r['mode']!='stock':assert r['mixtureRoots']>0
  rows[r['jobId']]=r
assert set(rows)==set(jobs)and len(rows)==expected
controls={}
for job_id in sorted(rows):
 r=rows[job_id];j=jobs[job_id];key=(r['board'],r['game']);mode=r['mode']
 actual={'inputSha256':r['inputSha256'],'traceSha256':r['traceSha256'],'score':r['score'],'winner':r['winner'],
         'actualTurnsSha256':hashlib.sha256(json.dumps(r['actualTurns'],separators=(',',':'),ensure_ascii=False).encode()).hexdigest()}
 if mode=='both':
  if key not in controls:
   assert not r['live']and r['expectedTraceSha256']is None
   controls[key]=actual
  else:
   assert actual==controls[key]
   assert r['expectedTraceSha256']==controls[key]['traceSha256']and r['expectedScore']==controls[key]['score']and r['expectedWinner']==controls[key]['winner']
 else:
  assert actual==original[key][mode],(key,mode,'Original full input/trace/outcome/actual-turn control changed')
  assert r['expectedTraceSha256']==j['expectedTraceSha256']and r['expectedScore']==j['expectedScore']and r['expectedWinner']==j['expectedWinner']
assert len(controls)==caseCount
stored={(r['board'],r['game']):r for r in json.loads((out/'established-both-controls.json').read_text())}
assert set(stored)==set(controls)
for key,control in controls.items():
 for field in ['inputSha256','traceSha256','score','winner']:assert stored[key][field]==control[field]
def metrics(subset):
 values=sorted(d['micros']for r in subset for d in r['decisionMicros']);total=sum(values)
 return {'fights':len(subset),'fightCpuMicros':sum(r['fightCpuMicros']for r in subset),
  'fightWallMicros':sum(r['fightWallMicros']for r in subset),'decisionMicros':total,'decisionCount':len(values),
  'meanDecisionMicros':total/len(values),
  'decisionTailMicros':{str(q):values[math.floor(q*(len(values)-1))]for q in [.5,.9,.95,.99,1]},
  'rolloutTurns':sum(w['rolloutTurnsTotal']for r in subset for w in r['quality']['work'])}
def ratio(a,b,key):return a[key]/b[key]
def within(a,b,key):
 if key=='meanDecisionMicros':return 10*a['decisionMicros']*b['decisionCount']<=11*b['decisionMicros']*a['decisionCount']
 return 10*a[key]<=11*b[key]
phases={};gates={};diagnostics={}
for phase in ['offline-full-r2','bounded-live-full-r2']:
 arms={m:metrics([r for r in rows.values()if r['phase']==phase and not r['warmup']and r['mode']==m])for m in ['stock','mixture','both']}
 assert all(a['fights']==caseCount for a in arms.values())
 ratios={}
 for mode in ['mixture','both']:
  ratios[mode]={}
  for key in ['fightCpuMicros','fightWallMicros','decisionMicros','meanDecisionMicros']:
   ratios[mode][key]=ratio(arms[mode],arms['stock'],key)
   gates[f'{phase}/{mode}/{key}<=1.10']=within(arms[mode],arms['stock'],key)
 phases[phase]={'arms':arms,'ratiosVsStock':ratios}
 diagnostics[phase]={}
 for field in ['map','ownDoctrine','opponentDoctrine','opponentStyle']:
  groups={}
  for value in sorted({r[field]for r in rows.values()if r['phase']==phase and not r['warmup']},key=str):
   grouped={m:metrics([r for r in rows.values()if r['phase']==phase and not r['warmup']and r['mode']==m and r[field]==value])for m in ['stock','mixture','both']}
   groups[str(value)]={'arms':grouped,'ratiosVsStock':{m:{k:ratio(grouped[m],grouped['stock'],k)for k in ['fightCpuMicros','fightWallMicros','decisionMicros','meanDecisionMicros']}for m in ['mixture','both']}}
  diagnostics[phase][field]=groups
result={'id':reg['id'],'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'complete':True,
 'executions':expected,'variant':variant,'cases':caseCount,'registrationSha256':seal,'allOriginalStockMixtureInputsFullTracesOutcomesAndActualTurnsExact':True,
 'allBothDriverOfflineRepeatsAndLiveControlsExact':True,'zeroEngineModelOrTimingFailures':True,
 'phases':phases,'gates':gates,'costGatePassed':all(gates.values()),'descriptiveSubgroupsOnly':diagnostics,
 'userBudgetTarget':'Overall average (+10%)','thresholdEvaluation':'Exact integer crossmultiplication; mean uses decision-total/count crossproducts.',
 'rawSha256':rawsha,'defaultChanged':False,'deployed':False,
 'scope':'Prospectively preselected freshv11cases, one active fight, pure nativebaseline, no accepted-model wrapper, real clocks. '
 'Fixed aggregate gate includes both one- and two-actual-driver modes offline/live. Subgroups/tails descriptive. '
 'No independent strength evidence or general production two-vCPU latency certification from this validation.'}
with(out/'analysis.json').open('x')as f:f.write(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items()if k not in ['descriptiveSubgroupsOnly','rawSha256']},indent=2))

