import assert from"node:assert/strict";
import{readFileSync,writeFileSync}from"node:fs";
import{createHash}from"node:crypto";
import{gunzipSync}from"node:zlib";
const variant=process.argv[2]??"primary";assert(["primary","coverage"].includes(variant));
const stem=variant==="primary"?"v11-cost":"v11-coverage-cost",expected=variant==="primary"?464:1328,caseCount=variant==="primary"?72:216;
const p=import.meta.dir,read=(n:string)=>JSON.parse(readFileSync(`${p}/${n}`,"utf8"));
const a=read(`${stem}/analysis.json`),regraw=readFileSync(`${p}/${stem}-registration.json`);
assert.equal(createHash("sha256").update(regraw).digest("hex"),a.registrationSha256);
const reg=JSON.parse(regraw.toString());assert.equal(reg.variant,variant);assert.equal(reg.executions,expected);assert.equal(reg.preselectedCases,caseCount);
const status=read(`${stem}/status.json`);assert(status.complete&&!status.errors.length&&!status.liveWorkerPids.length);
const jobs=new Map<number,any>(read(`${stem}-jobs.json`).map((j:any)=>[j.jobId,j]));
const original=new Map<string,any>(JSON.parse(gunzipSync(readFileSync(`${p}/complete-trace-index.json.gz`)).toString()).map((r:any)=>[`${r.board}/${r.game}`,r.arms]));
const records=new Map<number,any>();
for(const implementation of["baseline","candidate"]){
 const file=`${implementation}.jsonl.gz`,raw=readFileSync(`${p}/${stem}/${file}`);
 assert.equal(createHash("sha256").update(raw).digest("hex"),a.rawSha256[file]);
 for(const line of gunzipSync(raw).toString().trim().split("\n")){
  const r=JSON.parse(line),j=jobs.get(r.jobId);assert(j&&!records.has(r.jobId));
  assert.equal(r.registrationSha256,a.registrationSha256);assert.equal(r.implementation,implementation);assert.equal(r.implementation,j.implementation);
  for(const k of["mode","phase","live","warmup","ordinal","board","game","seed"])assert.equal(r[k],j[k]);
  assert.equal(r.inputSha256,j.expectedInputSha256);assert.equal(r.quality.rejected,0);
  for(const n of r.quality.neural){assert.equal(n.modelErrors,0);assert.equal(n.missingStart,0);}
  for(const w of r.quality.work)for(const k of["deadlineFallbacks","circuitSkipped","circuitWaitArbitrations","degradedDecisions"])assert.equal(w[k]??0,0);
  assert(Number.isSafeInteger(r.fightCpuMicros)&&r.fightCpuMicros>0);assert(Number.isSafeInteger(r.fightWallMicros)&&r.fightWallMicros>0);
  assert(r.decisionMicros.length);for(const d of r.decisionMicros)assert(Number.isSafeInteger(d.micros)&&d.micros>=0);
  if(r.mode!=="stock")assert(r.mixtureRoots>0);
  records.set(r.jobId,r);
 }
}
assert.equal(records.size,expected);assert.equal(records.size,jobs.size);
const controls=new Map<string,any>();
for(const[id,r]of[...records].sort(([a],[b])=>a-b)){
 const j=jobs.get(id),key=`${r.board}/${r.game}`,actual={inputSha256:r.inputSha256,traceSha256:r.traceSha256,score:r.score,winner:r.winner};
 if(r.mode==="both"){
  if(!controls.has(key)){assert(!r.live);assert.equal(r.expectedTraceSha256,null);controls.set(key,actual);}
  else{assert.deepEqual(actual,controls.get(key));assert.equal(r.expectedTraceSha256,actual.traceSha256);assert.equal(r.expectedScore,actual.score);assert.equal(r.expectedWinner,actual.winner);}
 }else{
  const wanted=original.get(key)[r.mode];for(const[k,v]of Object.entries(actual))assert.equal(v,wanted[k]);
  assert.equal(r.expectedTraceSha256,j.expectedTraceSha256);assert.equal(r.expectedScore,j.expectedScore);assert.equal(r.expectedWinner,j.expectedWinner);
 }
}
assert.equal(controls.size,caseCount);
const gates:Record<string,boolean>={};
for(const phase of["offline-full-r2","bounded-live-full-r2"]){
 const totals:Record<string,any>={};
 for(const mode of["stock","mixture","both"]){
  const rows=[...records.values()].filter(r=>r.phase===phase&&!r.warmup&&r.mode===mode);assert.equal(rows.length,caseCount);
  const values=rows.flatMap(r=>r.decisionMicros.map((d:any)=>d.micros));
  const m={fightCpuMicros:rows.reduce((s,r)=>s+r.fightCpuMicros,0),fightWallMicros:rows.reduce((s,r)=>s+r.fightWallMicros,0),decisionMicros:values.reduce((s,n)=>s+n,0),decisionCount:values.length,meanDecisionMicros:values.reduce((s,n)=>s+n,0)/values.length};
  for(const[k,v]of Object.entries(m))assert.equal(v,a.phases[phase].arms[mode][k]);totals[mode]=m;
 }
 for(const mode of["mixture","both"])for(const key of["fightCpuMicros","fightWallMicros","decisionMicros","meanDecisionMicros"]){
  const m=totals[mode],s=totals.stock,ratio=m[key]/s[key];assert.equal(ratio,a.phases[phase].ratiosVsStock[mode][key]);
  const within=key==="meanDecisionMicros"?10n*BigInt(m.decisionMicros)*BigInt(s.decisionCount)<=11n*BigInt(s.decisionMicros)*BigInt(m.decisionCount):10n*BigInt(m[key])<=11n*BigInt(s[key]);
  gates[`${phase}/${mode}/${key}<=1.10`]=within;
 }
}
assert.deepEqual(gates,a.gates);assert.equal(Object.values(gates).every(Boolean),a.costGatePassed);
const result={passed:true,at:new Date().toISOString(),independentRawIntegerTimesRatiosAndExactBigIntGates:true,
 allOriginalStockMixtureAndEstablishedBothTraceControlsExact:true,costGatePassed:Object.values(gates).every(Boolean),
 analysisSha256:createHash("sha256").update(readFileSync(`${p}/${stem}/analysis.json`)).digest("hex")};
writeFileSync(`${p}/${stem}/independent-verification.json`,JSON.stringify(result,null,2)+"\n");console.log(JSON.stringify(result));
